import type { Request, RequestHandler } from 'express';

import {
  LocationGeocodingTimeoutError,
  LocationGeocodingUpstreamError,
} from './location-geocoding.service';
import {
  WeatherTimeoutError,
  WeatherUpstreamError,
  WeatherValidationError,
} from './weather.service';
import { GeocodingTimeoutError, GeocodingUpstreamError } from './geocoding.service';
import type { FixtureWeatherService } from './fixture-weather.service';

function pathParameter(request: Request, name: string): string {
  const value = request.params[name];
  if (value === undefined) {
    throw new Error(`Expected route parameter "${name}" was not provided.`);
  }
  return value;
}

export function getFixtureWeather(service: FixtureWeatherService): RequestHandler {
  return (request, response) => {
    void (async () => {
      try {
        const result = await service.getFixtureWeather(pathParameter(request, 'fixtureId'));
        if (!result) {
          response.status(404).json({
            error: { code: 'NOT_FOUND', message: 'Fixture not found.' },
          });
          return;
        }

        response.status(200).json({ data: result });
      } catch (error) {
        request.log?.error({ err: error }, 'Fixture weather API request failed');

        if (error instanceof WeatherValidationError) {
          response.status(503).json({
            error: {
              code: 'WEATHER_SERVICE_UNAVAILABLE',
              message: 'Weather information is temporarily unavailable.',
            },
          });
          return;
        }

        if (error instanceof WeatherTimeoutError || error instanceof GeocodingTimeoutError) {
          response.status(504).json({
            error: {
              code: 'UPSTREAM_TIMEOUT',
              message: 'The weather provider did not respond in time.',
            },
          });
          return;
        }

        if (error instanceof WeatherUpstreamError || error instanceof GeocodingUpstreamError) {
          response.status(502).json({
            error: { code: 'UPSTREAM_ERROR', message: 'The weather provider returned an error.' },
          });
          return;
        }

        if (error instanceof LocationGeocodingTimeoutError) {
          response.status(504).json({
            error: {
              code: 'UPSTREAM_TIMEOUT',
              message: 'The location provider did not respond in time.',
            },
          });
          return;
        }

        if (error instanceof LocationGeocodingUpstreamError) {
          response.status(502).json({
            error: { code: 'UPSTREAM_ERROR', message: 'The location provider returned an error.' },
          });
          return;
        }

        response.status(503).json({
          error: {
            code: 'WEATHER_SERVICE_UNAVAILABLE',
            message: 'Weather information is temporarily unavailable.',
          },
        });
      }
    })();
  };
}

export interface GeocodedLocation {
  latitude: number;
  longitude: number;
}

interface OpenMeteoGeocodingResponse {
  results?: Array<{ latitude?: number; longitude?: number }>;
}

const GEOCODING_BASE_URL = 'https://geocoding-api.open-meteo.com/v1/search';
const REQUEST_TIMEOUT_MS = 5000;

export class LocationGeocodingTimeoutError extends Error {
  constructor(message = 'The location geocoding request timed out') {
    super(message);
    this.name = 'LocationGeocodingTimeoutError';
  }
}

export class LocationGeocodingUpstreamError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'LocationGeocodingUpstreamError';
  }
}

export interface LocationGeocodingService {
  resolve(query: string): Promise<GeocodedLocation | null>;
}

export class OpenMeteoLocationGeocodingService implements LocationGeocodingService {
  async resolve(query: string): Promise<GeocodedLocation | null> {
    const url = new URL(GEOCODING_BASE_URL);
    url.searchParams.set('name', query);
    url.searchParams.set('count', '1');
    url.searchParams.set('language', 'en');
    url.searchParams.set('format', 'json');
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

    try {
      const response = await fetch(url.toString(), { signal: controller.signal });
      if (!response.ok) {
        throw new LocationGeocodingUpstreamError(
          `Open-Meteo geocoding request failed with status ${response.status}`,
        );
      }
      let data: OpenMeteoGeocodingResponse;
      try {
        data = (await response.json()) as OpenMeteoGeocodingResponse;
      } catch {
        throw new LocationGeocodingUpstreamError('Open-Meteo geocoding returned invalid JSON');
      }
      const result = data.results?.find(
        (candidate) =>
          Number.isFinite(candidate.latitude) &&
          Number.isFinite(candidate.longitude) &&
          candidate.latitude! >= -90 &&
          candidate.latitude! <= 90 &&
          candidate.longitude! >= -180 &&
          candidate.longitude! <= 180,
      );
      return result?.latitude === undefined || result.longitude === undefined
        ? null
        : { latitude: result.latitude, longitude: result.longitude };
    } catch (error) {
      if (error instanceof LocationGeocodingUpstreamError) throw error;
      if (error instanceof Error && error.name === 'AbortError') {
        throw new LocationGeocodingTimeoutError();
      }
      throw new LocationGeocodingUpstreamError('Unable to reach Open-Meteo geocoding service');
    } finally {
      clearTimeout(timeout);
    }
  }
}

import { resolve } from 'node:path';
import { Pool, type PoolClient } from 'pg';
import { afterAll, beforeAll, describe, expect, test } from 'vitest';

import { ingestMatchData } from '../../scripts/ingest-match-data';
import { assertSafeTestDatabase } from '../../scripts/test-database-safety';
import {
  findFixtureById,
  findFixtureWeatherContext,
  listFixtures,
  updateVenueCoordinates,
} from '../../src/modules/fixtures/fixture.repository';
import { findSeason, listSeasons } from '../../src/modules/seasons/season.repository';

const seedPath = resolve(__dirname, '../../../../database/seeds/matches/423788.json');
const sourceRef = `issue-192-public-read-${process.pid}`;

describe.sequential('public read relationship summaries database integration', () => {
  let pool: Pool | undefined;
  let client: PoolClient | undefined;
  let fixtureId: string | undefined;

  function databaseClient(): PoolClient {
    if (!client) {
      throw new Error('Test database client has not been initialised.');
    }

    return client;
  }

  function ingestedFixtureId(): string {
    if (!fixtureId) {
      throw new Error('Reference fixture has not been ingested.');
    }

    return fixtureId;
  }

  beforeAll(async () => {
    const databaseUrl = assertSafeTestDatabase(
      process.env.DATABASE_URL_TEST,
      process.env.DATABASE_URL,
      process.env.NODE_ENV,
    );

    pool = new Pool({ connectionString: databaseUrl.toString() });
    client = await pool.connect();
    await client.query('BEGIN');

    try {
      const ingestion = await ingestMatchData(client, seedPath, { sourceRef });
      fixtureId = ingestion.fixtureId;
    } catch (error) {
      await client.query('ROLLBACK').catch(() => undefined);
      client.release();
      client = undefined;
      await pool.end();
      pool = undefined;
      throw error;
    }
  }, 30_000);

  afterAll(async () => {
    if (client) {
      await client.query('ROLLBACK').catch(() => undefined);
      client.release();
      client = undefined;
    }

    if (pool) {
      await pool.end();
      pool = undefined;
    }
  });

  test('returns seasons with their readable competition name', async () => {
    const executor = databaseClient();

    const page = await listSeasons(
      {
        limit: 50,
      },
      executor,
    );

    const season = page.records.find(
      (record) =>
        record.label === '2009/10' &&
        record.competitionName === 'Australia in New Zealand T20I Series',
    );

    expect(season).toBeDefined();

    if (!season) {
      throw new Error('Expected the ingested competition season.');
    }

    const detail = await findSeason(season.competitionId, season.label, executor);

    expect(detail).toEqual({
      competitionId: season.competitionId,
      competitionName: 'Australia in New Zealand T20I Series',
      label: '2009/10',
    });
  });

  test('searches seasons by season label or competition name before pagination', async () => {
    const executor = databaseClient();

    const byCompetition = await listSeasons({ limit: 1, name: 'New Zealand T20I' }, executor);
    const byLabel = await listSeasons({ limit: 1, name: '2009/10' }, executor);

    expect(byCompetition.records).toEqual([
      expect.objectContaining({
        competitionName: 'Australia in New Zealand T20I Series',
        label: '2009/10',
      }),
    ]);
    expect(byLabel.records).toEqual([
      expect.objectContaining({
        competitionName: 'Australia in New Zealand T20I Series',
        label: '2009/10',
      }),
    ]);
  });

  test('returns fixtures with readable competition and participating team summaries', async () => {
    const executor = databaseClient();
    const currentFixtureId = ingestedFixtureId();

    const fixture = await findFixtureById(currentFixtureId, executor);

    expect(fixture).not.toBeNull();

    expect(fixture).toMatchObject({
      fixtureId: currentFixtureId,
      competitionName: 'Australia in New Zealand T20I Series',
      season: '2009/10',
    });

    expect(fixture?.competitors).toEqual(
      expect.arrayContaining([
        {
          name: 'New Zealand',
          competitorId: expect.any(String),
        },
        {
          name: 'Australia',
          competitorId: expect.any(String),
        },
      ]),
    );

    const page = await listFixtures(
      {
        limit: 50,
      },
      executor,
    );

    const listedFixture = page.records.find((record) => record.fixtureId === currentFixtureId);

    expect(listedFixture).toMatchObject({
      fixtureId: currentFixtureId,
      competitionName: 'Australia in New Zealand T20I Series',
      season: '2009/10',
    });

    expect(listedFixture?.competitors).toEqual(
      expect.arrayContaining([
        {
          name: 'New Zealand',
          competitorId: expect.any(String),
        },
        {
          name: 'Australia',
          competitorId: expect.any(String),
        },
      ]),
    );
  });

  test('returns stored venue coordinates for fixture weather resolution', async () => {
    const executor = databaseClient();
    const currentFixtureId = ingestedFixtureId();

    const initial = await findFixtureWeatherContext(currentFixtureId, executor);
    const venueId = initial?.venue?.venueId;
    expect(venueId).toBeDefined();

    await updateVenueCoordinates(venueId!, -43.4894, 172.5405, executor);

    await expect(findFixtureWeatherContext(currentFixtureId, executor)).resolves.toMatchObject({
      fixtureId: currentFixtureId,
      date: '2010-02-28',
      venue: {
        name: 'AMI Stadium',
        latitude: -43.4894,
        longitude: 172.5405,
      },
    });
  });
});

