import {
  type GeocodedLocation,
  type LocationGeocodingService,
  OpenMeteoLocationGeocodingService,
} from './location-geocoding.service';
import { classifyWeatherDate, type WeatherData, type WeatherService } from './weather.service';

type FixtureWeatherUnavailableReason =
  | 'MISSING_VENUE'
  | 'MISSING_COORDINATES'
  | 'UNSUPPORTED_LOCATION'
  | 'LOCATION_NOT_FOUND'
  | 'UNSUPPORTED_DATE';

export interface FixtureWeatherContext {
  fixtureId: string;
  date: string;
  venue: {
    venueId: string;
    name: string;
    city: string | null;
    latitude: number | null;
    longitude: number | null;
  } | null;
}

interface FixtureWeatherAvailable {
  fixtureId: string;
  date: string;
  availability: 'available';
  venue: { name: string; city: string | null };
  weather: WeatherData;
}

interface FixtureWeatherUnavailable {
  fixtureId: string;
  date: string;
  availability: 'unavailable';
  reason: FixtureWeatherUnavailableReason;
  venue: { name: string; city: string | null } | null;
  weather: null;
}

type FixtureWeatherResult = FixtureWeatherAvailable | FixtureWeatherUnavailable;

type FindFixtureWeatherContext = (fixtureId: string) => Promise<FixtureWeatherContext | null>;

type PersistVenueCoordinates = (
  venueId: string,
  latitude: number,
  longitude: number,
) => Promise<void>;

const databaseIdPattern = /^\d+$/;

interface Coordinates {
  latitude: number;
  longitude: number;
}

function hasUsableCoordinates(coordinates: Coordinates): boolean {
  return (
    Number.isFinite(coordinates.latitude) &&
    Number.isFinite(coordinates.longitude) &&
    coordinates.latitude >= -90 &&
    coordinates.latitude <= 90 &&
    coordinates.longitude >= -180 &&
    coordinates.longitude <= 180
  );
}

export interface FixtureWeatherService {
  getFixtureWeather(fixtureId: string): Promise<FixtureWeatherResult | null>;
}

export function createFixtureWeatherService(
  weatherService: WeatherService,
  findContext: FindFixtureWeatherContext = findFixtureWeatherContext,
  geocodingService: LocationGeocodingService = new OpenMeteoLocationGeocodingService(),
  persistVenueCoordinates: PersistVenueCoordinates = updateVenueCoordinates,
): FixtureWeatherService {
  return {
    async getFixtureWeather(fixtureId) {
      if (!databaseIdPattern.test(fixtureId)) {
        return null;
      }

      const context = await findContext(fixtureId);
      if (!context) {
        return null;
      }

      if (!context.venue) {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'MISSING_VENUE',
          venue: null,
          weather: null,
        };
      }

      const venue = {
        name: context.venue.name,
        city: context.venue.city,
      };

      if (classifyWeatherDate(context.date) === 'unsupported') {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'UNSUPPORTED_DATE',
          venue,
          weather: null,
        };
      }

      let latitude = context.venue.latitude;
      let longitude = context.venue.longitude;

      if (
        !hasUsableCoordinates({
          latitude: latitude ?? Number.NaN,
          longitude: longitude ?? Number.NaN,
        })
      ) {
        const queries = context.venue.city
          ? [`${context.venue.name}, ${context.venue.city}`, context.venue.name]
          : [context.venue.name];

        let resolved: GeocodedLocation | null = null;

        for (const query of queries) {
          resolved = await geocodingService.resolve(query);

          if (resolved) {
            break;
          }
        }

        if (!resolved) {
          return {
            fixtureId: context.fixtureId,
            date: context.date,
            availability: 'unavailable',
            reason: 'LOCATION_NOT_FOUND',
            venue,
            weather: null,
          };
        }

        latitude = resolved.latitude;
        longitude = resolved.longitude;

        if (!hasUsableCoordinates({ latitude, longitude })) {
          return {
            fixtureId: context.fixtureId,
            date: context.date,
            availability: 'unavailable',
            reason: 'UNSUPPORTED_LOCATION',
            venue,
            weather: null,
          };
        }

        await persistVenueCoordinates(context.venue.venueId, latitude, longitude);
      }

      const resolvedCoordinates = {
        latitude,
        longitude,
      };

      if (!hasUsableCoordinates(resolvedCoordinates)) {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'UNSUPPORTED_LOCATION',
          venue,
          weather: null,
        };
      }

      const weather = await weatherService.getWeather(
        resolvedCoordinates.latitude,
        resolvedCoordinates.longitude,
        context.date,
      );

      return {
        fixtureId: context.fixtureId,
        date: context.date,
        availability: 'available',
        venue,
        weather,
      };
    },
  };
}

export interface WeatherData {
  date: string;
  latitude: number;
  longitude: number;
  temperatureMax: number | null;
  temperatureMin: number | null;
  precipitationSum: number | null;
  windSpeedMax: number | null;
}

interface OpenMeteoResponse {
  daily?: {
    time?: string[];
    temperature_2m_max?: number[];
    temperature_2m_min?: number[];
    precipitation_sum?: number[];
    wind_speed_10m_max?: number[];
  };
}

const FORECAST_BASE_URL = 'https://api.open-meteo.com/v1/forecast';
const ARCHIVE_BASE_URL = 'https://archive-api.open-meteo.com/v1/archive';

// Open-Meteo's forecast endpoint covers roughly the last 92 days through 16 days ahead.
const FORECAST_PAST_DAYS_LIMIT = 92;
const FORECAST_FUTURE_DAYS_LIMIT = 16;

// Open-Meteo's archive (ERA5 reanalysis) endpoint covers 1940-01-01 onward.
const ARCHIVE_EARLIEST_DATE = '1940-01-01';

const REQUEST_TIMEOUT_MS = 5000;

export type WeatherEndpoint = 'forecast' | 'archive';

/**
 * Determines which Open-Meteo endpoint supports the requested date, relative to
 * `referenceDate` (defaults to now). Returns `'unsupported'` when the date falls
 * outside both the forecast and archive endpoints' supported ranges.
 */
export function classifyWeatherDate(
  date: string,
  referenceDate: Date = new Date(),
): WeatherEndpoint | 'unsupported' {
  const target = new Date(`${date}T00:00:00Z`);
  const today = new Date(
    Date.UTC(
      referenceDate.getUTCFullYear(),
      referenceDate.getUTCMonth(),
      referenceDate.getUTCDate(),
    ),
  );
  const diffDays = Math.round((target.getTime() - today.getTime()) / 86_400_000);

  if (diffDays > FORECAST_FUTURE_DAYS_LIMIT) {
    return 'unsupported';
  }

  if (diffDays >= -FORECAST_PAST_DAYS_LIMIT) {
    return 'forecast';
  }

  if (date >= ARCHIVE_EARLIEST_DATE) {
    return 'archive';
  }

  return 'unsupported';
}

export class WeatherValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'WeatherValidationError';
  }
}

export class WeatherTimeoutError extends Error {
  constructor(message = 'Open-Meteo request timed out') {
    super(message);
    this.name = 'WeatherTimeoutError';
  }
}

export class WeatherUpstreamError extends Error {
  constructor(
    message: string,
    readonly status?: number,
  ) {
    super(message);
    this.name = 'WeatherUpstreamError';
  }
}

export class WeatherDateUnsupportedError extends Error {
  constructor(message = 'Weather data is not available for the requested date') {
    super(message);
    this.name = 'WeatherDateUnsupportedError';
  }
}

export class WeatherService {
  async getWeather(latitude: number, longitude: number, date: string): Promise<WeatherData> {
    this.validateCoordinates(latitude, longitude);
    this.validateDate(date);

    const endpoint = classifyWeatherDate(date);

    if (endpoint === 'unsupported') {
      throw new WeatherDateUnsupportedError();
    }

    const url = new URL(endpoint === 'archive' ? ARCHIVE_BASE_URL : FORECAST_BASE_URL);

    url.searchParams.set('latitude', latitude.toString());
    url.searchParams.set('longitude', longitude.toString());
    url.searchParams.set('start_date', date);
    url.searchParams.set('end_date', date);
    url.searchParams.set(
      'daily',
      ['temperature_2m_max', 'temperature_2m_min', 'precipitation_sum', 'wind_speed_10m_max'].join(
        ',',
      ),
    );
    url.searchParams.set('timezone', 'auto');

    const response = await this.fetchWithRetry(url.toString());

    if (!response.ok) {
      throw new WeatherUpstreamError(
        `Open-Meteo request failed with status ${response.status}`,
        response.status,
      );
    }

    let data: OpenMeteoResponse;

    try {
      data = (await response.json()) as OpenMeteoResponse;
    } catch {
      throw new WeatherUpstreamError('Open-Meteo returned invalid JSON');
    }

    return this.parseWeatherResponse(data, latitude, longitude, date);
  }

  private async fetchWithTimeout(url: string): Promise<Response> {
    const controller = new AbortController();

    const timeout = setTimeout(() => {
      controller.abort();
    }, REQUEST_TIMEOUT_MS);

    try {
      return await fetch(url, {
        signal: controller.signal,
      });
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        throw new WeatherTimeoutError();
      }

      throw new WeatherUpstreamError('Unable to reach Open-Meteo');
    } finally {
      clearTimeout(timeout);
    }
  }

  private async fetchWithRetry(url: string): Promise<Response> {
    try {
      const firstResponse = await this.fetchWithTimeout(url);
      if (!this.isRetryableStatus(firstResponse.status)) {
        return firstResponse;
      }
    } catch (error) {
      if (!this.isRetryableError(error)) {
        throw error;
      }
    }

    return this.fetchWithTimeout(url);
  }

  private isRetryableStatus(status: number): boolean {
    return status === 408 || status >= 500;
  }

  private isRetryableError(error: unknown): boolean {
    return error instanceof WeatherTimeoutError || error instanceof WeatherUpstreamError;
  }

  private parseWeatherResponse(
    data: OpenMeteoResponse,
    latitude: number,
    longitude: number,
    date: string,
  ): WeatherData {
    const daily = data.daily;

    if (
      !daily ||
      !Array.isArray(daily.time) ||
      !Array.isArray(daily.temperature_2m_max) ||
      !Array.isArray(daily.temperature_2m_min) ||
      !Array.isArray(daily.precipitation_sum) ||
      !Array.isArray(daily.wind_speed_10m_max)
    ) {
      throw new WeatherUpstreamError('Open-Meteo returned an invalid weather response');
    }

    const dateIndex = daily.time.indexOf(date);

    if (dateIndex === -1) {
      throw new WeatherUpstreamError('Weather data was not available for the requested date');
    }

    return {
      date,
      latitude,
      longitude,
      temperatureMax: daily.temperature_2m_max[dateIndex] ?? null,
      temperatureMin: daily.temperature_2m_min[dateIndex] ?? null,
      precipitationSum: daily.precipitation_sum[dateIndex] ?? null,
      windSpeedMax: daily.wind_speed_10m_max[dateIndex] ?? null,
    };
  }

  private validateCoordinates(latitude: number, longitude: number): void {
    if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90) {
      throw new WeatherValidationError('Latitude must be between -90 and 90');
    }

    if (!Number.isFinite(longitude) || longitude < -180 || longitude > 180) {
      throw new WeatherValidationError('Longitude must be between -180 and 180');
    }
  }

  private validateDate(date: string): void {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      throw new WeatherValidationError('Date must use YYYY-MM-DD format');
    }

    const parsedDate = new Date(`${date}T00:00:00Z`);

    if (Number.isNaN(parsedDate.getTime())) {
      throw new WeatherValidationError('Invalid date');
    }
  }
}

import { useCallback, useEffect, useState } from 'react';

type PublicDataState<Data> =
  | { status: 'loading'; data: null; error: null }
  | { status: 'ready'; data: Data; error: null }
  | { status: 'error'; data: null; error: Error };

export function usePublicData<Data>(
  load: (signal: AbortSignal) => Promise<Data>,
  requestKey: string,
) {
  const [reloadCount, setReloadCount] = useState(0);
  const [state, setState] = useState<PublicDataState<Data>>({
    status: 'loading',
    data: null,
    error: null,
  });

  useEffect(() => {
    const controller = new AbortController();
    setState({ status: 'loading', data: null, error: null });

    void load(controller.signal)
      .then((data) => {
        if (!controller.signal.aborted) {
          setState({ status: 'ready', data, error: null });
        }
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) {
          setState({
            status: 'error',
            data: null,
            error: error instanceof Error ? error : new Error('The public API request failed.'),
          });
        }
      });

    return () => controller.abort();
  }, [load, reloadCount, requestKey]);

  const reload = useCallback(() => setReloadCount((count) => count + 1), []);

  return { ...state, reload };
}

